/// Human-readable display name for an audio effect type id. Matches
/// the FX library's display labels so a user sees the same string in
/// the bypass-strip tooltip as in the "+ Add Effect" picker. LADSPA
/// plugins fall back to the path's last segment.
fn effect_display_name(type_id: &str) -> String {
    if let Some(rest) = type_id.strip_prefix("ladspa:") {
        // "ladspa:/path/to/lib.so:LabelName" — take everything after
        // the last `:`. Path may contain colons (rare) so split from
        // the right.
        if let Some(label) = rest.rsplit(':').next() {
            return label.to_string();
        }
    }
    match type_id {
        "eq" => "EQ".into(),
        "compressor" => "Compressor".into(),
        "limiter" => "Limiter".into(),
        "gate" => "Gate".into(),
        "deesser" => "De-esser".into(),
        "normalize" => "Normalize".into(),
        "reverb" => "Reverb".into(),
        "delay" => "Delay".into(),
        "chorus" => "Chorus".into(),
        "declick" => "Declick".into(),
        "noise_reduction" => "Multi-band Gate".into(),
        "multiband_compressor" => "Multi-band Compressor".into(),
        "pitch_shift" => "Pitch Shift".into(),
        other => other.to_string(),
    }
}

/// Build the ordered list of `RubberBandParam`s the user can rotate
/// through on a given clip — the SAME list the popup picker shows
/// (clip-level Volume/Pan/Gain, then per-effect kf'd params grouped
/// by effect index, alphabetical within each group). Used by both
/// the click-popup (B3) and the wheel-cycle (D) so the orderings
/// stay in lockstep — you can't end up with the popup highlighting
/// one item while wheel-scroll lands on a different one.
fn build_rubber_band_picker_list(clip_kf_keys: &[String]) -> Vec<crate::state::RubberBandParam> {
    let mut list = vec![
        crate::state::RubberBandParam::ClipParam(klipp_core::AudioParam::Volume),
        crate::state::RubberBandParam::ClipParam(klipp_core::AudioParam::Pan),
        crate::state::RubberBandParam::ClipParam(klipp_core::AudioParam::Gain),
    ];
    let mut by_effect: std::collections::BTreeMap<usize, Vec<String>> =
        std::collections::BTreeMap::new();
    for key in clip_kf_keys {
        if let Some((idx_str, name)) = key.split_once(':') {
            if let Ok(idx) = idx_str.parse::<usize>() {
                by_effect.entry(idx).or_default().push(name.to_string());
            }
        }
    }
    for (idx, mut names) in by_effect {
        names.sort();
        for name in names {
            list.push(crate::state::RubberBandParam::EffectParam {
                effect_index: idx,
                param_name: name,
            });
        }
    }
    list
}

/// Pick the "primary" kf'd param to surface when the user clicks a
/// top-strip cell on an audio clip. Order:
///   1. First non-reserved param name, alphabetical (a real tunable
///      like `gain`/`threshold` is what the user is most likely
///      automating + most likely wants to see first).
///   2. `__wetdry` (continuous control, more interesting than bypass).
///   3. `__bypass` (binary on/off — least interesting envelope to
///      visualise as a rubber band).
///
/// Returns `None` if `params` is empty.
fn pick_primary_kf_param(params: &[String]) -> Option<String> {
    let mut sorted: Vec<&String> = params.iter().collect();
    sorted.sort();
    sorted
        .iter()
        .find(|n| !n.starts_with("__"))
        .map(|s| (*s).clone())
        .or_else(|| sorted.iter().find(|n| n.as_str() == "__wetdry").map(|s| (*s).clone()))
        .or_else(|| sorted.iter().find(|n| n.as_str() == "__bypass").map(|s| (*s).clone()))
}

/// Pill label for the audio rubber band when it's showing an effect
/// param. Reserved keys (`__bypass`, `__wetdry`) get friendly names so
/// the pill doesn't read like a code literal.
fn format_effect_param_pill(effect_index: usize, param_name: &str) -> String {
    let pretty = match param_name {
        "__bypass" => "Bypass",
        "__wetdry" => "Mix",
        other => other,
    };
    format!("FX{effect_index}:{pretty}")
}

/// Formatted active/bypass time-range summary for a `__bypass` kf
/// track over a clip of `clip_dur_secs`. Implicit baseline is "active"
/// before the first kf. Used in the bypass-strip hover tooltip.
fn bypass_envelope_summary(
    kfs: &[klipp_core::Keyframe],
    clip_dur_secs: f64,
) -> String {
    if kfs.is_empty() {
        return "active throughout".into();
    }
    let fmt = |t: f64| -> String {
        if t < 60.0 { format!("{t:.2}s") } else {
            let m = (t / 60.0) as i64;
            let s = t - (m as f64) * 60.0;
            format!("{m}:{s:05.2}")
        }
    };
    let mut parts: Vec<String> = Vec::new();
    // Implicit "active" segment before the first kf.
    let first_t = kfs[0].time_secs.max(0.0).min(clip_dur_secs);
    if first_t > 0.001 {
        parts.push(format!("active {}–{}", fmt(0.0), fmt(first_t)));
    }
    for (i, kf) in kfs.iter().enumerate() {
        let next_t = if i + 1 < kfs.len() {
            kfs[i + 1].time_secs.min(clip_dur_secs)
        } else {
            clip_dur_secs
        };
        let t0 = kf.time_secs.max(0.0).min(clip_dur_secs);
        if next_t <= t0 + 0.001 { continue; }
        let label = if kf.value > 0.5 { "active" } else { "bypassed" };
        parts.push(format!("{label} {}–{}", fmt(t0), fmt(next_t)));
    }
    if parts.is_empty() {
        "active throughout".into()
    } else {
        parts.join(", ")
    }
}
// Default track heights — overridable via prefs.timeline (synced to state.timeline_prefs)
pub(crate) const VIDEO_TRACK_HEIGHT: f32 = 50.0;
pub(crate) const AUDIO_TRACK_HEIGHT: f32 = 48.0;
pub(crate) const TEXT_TRACK_HEIGHT: f32 = 32.0;
const MIN_TRACK_HEIGHT: f32 = 32.0;
/// The default cap a track is resized to (the preference's default);
/// the timeline reads the preference, the tests this.
#[cfg(test)]
const MAX_TRACK_HEIGHT: f32 = 300.0;

/// The tallest a track is resized to: the timeline preferences' max
/// track height, never below the smallest track.
pub(crate) fn track_height_cap(prefs: &crate::prefs::TimelinePrefs) -> f32 {
    prefs.max_track_height.max(MIN_TRACK_HEIGHT)
}

/// A track's height after its edge is dragged `delta` pixels from
/// `orig`: between the smallest track and the preferences' cap.
pub(crate) fn resized_track_height(orig: f32, delta: f32, prefs: &crate::prefs::TimelinePrefs) -> f32 {
    (orig + delta).clamp(MIN_TRACK_HEIGHT, track_height_cap(prefs))
}

/// Height of the per-track expandable automation lane when visible.
/// Matches DaVinci Fairlight's lane proportion — tall enough that drag
/// handles aren't fiddly, short enough that several tracks still fit.
pub(crate) const AUTOMATION_LANE_HEIGHT: f32 = 120.0;

/// Hard limits for the user-resizable lane. Min keeps the curve
/// readable (~3 ticks visible); max keeps the timeline usable.
pub(crate) const MIN_AUTOMATION_LANE_HEIGHT: f32 = 40.0;
pub(crate) const MAX_AUTOMATION_LANE_HEIGHT: f32 = 400.0;

/// Returns the height of the lane below the clip area, or 0 if the lane
/// is collapsed. Honours the per-track `automation_lane_height` override
/// when set; otherwise falls back to `AUTOMATION_LANE_HEIGHT`. Used by
/// Y-stacking, the lane painter, and the drag-handler rect math.
pub(crate) fn automation_lane_height(track: &klipp_timeline::Track) -> f32 {
    if track.automation_lane_visible.is_some() {
        track
            .automation_lane_height
            .map(|h| h.clamp(MIN_AUTOMATION_LANE_HEIGHT, MAX_AUTOMATION_LANE_HEIGHT))
            .unwrap_or(AUTOMATION_LANE_HEIGHT)
    } else {
        0.0
    }
}

/// Get effective track height (clip-area only — the part `clip_screen_rect`
/// sizes against). Respects `custom_height` override and prefs, but does
/// NOT include the expandable automation lane — the lane stacks below
/// this. Use [`track_row_height`] when you need the full row footprint
/// for Y-position accumulation.
pub(crate) fn effective_track_height(track: &klipp_timeline::Track) -> f32 {
    track.custom_height.unwrap_or(match track.kind {
        TrackKind::Audio => AUDIO_TRACK_HEIGHT,
        TrackKind::Text | TrackKind::Subtitle => TEXT_TRACK_HEIGHT,
        _ => VIDEO_TRACK_HEIGHT,
    })
}

/// Total Y footprint of a track row: clip area plus the automation lane
/// when visible. Use this in the timeline's track-stacking pass; clip
/// rectangle sizing still uses [`effective_track_height`].
pub(crate) fn track_row_height(track: &klipp_timeline::Track) -> f32 {
    effective_track_height(track) + automation_lane_height(track)
}

/// Apply the transient Fit scale to a track's full row without changing its
/// persisted/custom height. A scale below one is only used while fitting a
/// tall stack; normal interaction keeps the user's authored dimensions.
pub(crate) fn scaled_track_height(track: &klipp_timeline::Track, scale: f32) -> f32 {
    effective_track_height(track) * scale.clamp(0.1, 1.0)
}

pub(crate) fn scaled_track_row_height(track: &klipp_timeline::Track, scale: f32) -> f32 {
    track_row_height(track) * scale.clamp(0.1, 1.0)
}

/// Return the transient vertical scale needed to fit a track stack in the
/// visible timeline area. A normal-sized stack stays at authored size; only
/// an overflowing stack is compressed, with the same lower bound as the
/// timeline's other fit scales.
pub(crate) fn fit_track_scale(total_height: f32, available_height: f32) -> f32 {
    if total_height > 0.0 && available_height > 0.0 {
        (available_height / total_height).clamp(0.1, 1.0)
    } else {
        1.0
    }
}

/// Get effective track height using preferences for defaults.
#[allow(dead_code)]
fn effective_track_height_with_prefs(track: &klipp_timeline::Track, tl: &crate::prefs::TimelinePrefs) -> f32 {
    track.custom_height.unwrap_or(match track.kind {
        TrackKind::Audio => tl.min_track_height.max(AUDIO_TRACK_HEIGHT), // use pref default
        TrackKind::Text | TrackKind::Subtitle => tl.text_track_height,
        _ => tl.min_track_height.max(VIDEO_TRACK_HEIGHT),
    })
}

